// sees it as it sees any other. What it does not have is a value: a field
// with a validator is refused, since there is nothing for the validator to
// check, and so is one that only a create could write. A create refuses a
// mutation holding an expression at all.
func (m *Mutation) SetFieldExpr(name string, expr sql.Querier) error {
	if expr == nil {
		return fmt.Errorf("no expression for field %s", name)
	}
	if m.op.Is(ent.OpCreate) {
		return fmt.Errorf("field %s cannot be assigned an expression: a create writes values, and an expression is written only by an update", name)
	}
	switch name {
	case FieldPayer:
		return fmt.Errorf("field %s cannot be assigned an expression: it is immutable, and an expression is written only by an update", name)
	case FieldDateStart:
		return fmt.Errorf("field %s cannot be assigned an expression: it is immutable, and an expression is written only by an update", name)
	case FieldDateEnd:
		m.ResetDateEnd()
	case FieldBegan:
		return fmt.Errorf("field %s cannot be assigned an expression: it is immutable, and an expression is written only by an update", name)
	case FieldEnded:
		m.ResetEnded()
	case FieldDateUpdated:
		m.ResetDateUpdated()
	case FieldDateErased:
		m.ResetDateErased()
	case FieldDateCreated:
		return fmt.Errorf("field %s cannot be assigned an expression: it is immutable, and an expression is written only by an update", name)
	case FieldTenantId:
		return fmt.Errorf("field %s cannot be assigned an expression: it holds an edge, which is set through the edge", name)
	case FieldWorkspaceId:
		return fmt.Errorf("field %s cannot be assigned an expression: it holds an edge, which is set through the edge", name)
	case FieldBillingAccountId:
		return fmt.Errorf("field %s cannot be assigned an expression: it holds an edge, which is set through the edge", name)
	case FieldOfferId:
		return fmt.Errorf("field %s cannot be assigned an expression: it holds an edge, which is set through the edge", name)
	default:
		return fmt.Errorf("unknown Link field %s", name)
	}
	if m.exprs == nil {
		m.exprs = make(map[string]sql.Querier)
	}
	m.exprs[name] = expr
	return nil
}

// FieldExpr returns the expression the field with the given name was assigned
// by SetFieldExpr. The second return value reports whether it was.
func (m *Mutation) FieldExpr(name string) (sql.Querier, bool) {
	e, ok := m.exprs[name]
	return e, ok
}

// ExprFields returns the fields that were assigned an expression by
// SetFieldExpr.
func (m *Mutation) ExprFields() []string {
	var fields []string
	if _, ok := m.exprs[FieldDateEnd]; ok {
		fields = append(fields, FieldDateEnd)
	}
	if _, ok := m.exprs[FieldEnded]; ok {
		fields = append(fields, FieldEnded)
	}
	if _, ok := m.exprs[FieldDateUpdated]; ok {
		fields = append(fields, FieldDateUpdated)
	}
	if _, ok := m.exprs[FieldDateErased]; ok {
		fields = append(fields, FieldDateErased)
	}
	return fields
}

// AddedFields returns all numeric fields that were incremented/decremented during
// this mutation.
func (m *Mutation) AddedFields() []string {
	var fields []string
	if m.addbegan != nil {
		fields = append(fields, FieldBegan)
	}
	if m.addended != nil {
		fields = append(fields, FieldEnded)
	}
	return fields
}

// AddedField returns the numeric value that was incremented/decremented on a field
// with the given name. The second boolean return value indicates that this field
// was not set, or was not defined in the schema.
func (m *Mutation) AddedField(name string) (ent.Value, bool) {
	switch name {
	case FieldBegan:
		return m.AddedBegan()
	case FieldEnded:
		return m.AddedEnded()
	}
	return nil, false
}

// AddField adds the value to the field with the given name. It returns an error if
// the field is not defined in the schema, or if the type mismatched the field
// type.
func (m *Mutation) AddField(name string, value ent.Value) error {
	switch name {
	case FieldBegan:
		v, ok := value.(int32)
		if !ok {
			return fmt.Errorf("unexpected type %T for field %s", value, name)
		}
		m.AddBegan(v)
		return nil
	case FieldEnded:
		v, ok := value.(int32)
		if !ok {
			return fmt.Errorf("unexpected type %T for field %s", value, name)
		}
		m.AddEnded(v)
		return nil
	}
	return fmt.Errorf("unknown Link numeric field %s", name)
}

// ClearedFields returns all nullable fields that were cleared during this
// mutation.
func (m *Mutation) ClearedFields() []string {
	var fields []string
	if m.FieldCleared(FieldDateStart) {
		fields = append(fields, FieldDateStart)
	}
	if m.FieldCleared(FieldDateEnd) {
		fields = append(fields, FieldDateEnd)
	}
	if m.FieldCleared(FieldDateErased) {
		fields = append(fields, FieldDateErased)
	}
	if m.FieldCleared(FieldDateCreated) {
		fields = append(fields, FieldDateCreated)
	}
	if m.FieldCleared(FieldBillingAccountId) {
		fields = append(fields, FieldBillingAccountId)
	}
	if m.FieldCleared(FieldOfferId) {
		fields = append(fields, FieldOfferId)
	}
	return fields
}

// FieldCleared returns a boolean indicating if a field with the given name was
// cleared in this mutation.
func (m *Mutation) FieldCleared(name string) bool {
	_, ok := m.clearedFields[name]
	return ok
}

// ClearField clears the value of the field with the given name. It returns an
// error if the field is not defined in the schema.
func (m *Mutation) ClearField(name string) error {
	switch name {
	case FieldDateStart:
		m.ClearDateStart()
		return nil
	case FieldDateEnd:
		m.ClearDateEnd()
		return nil
	case FieldDateErased:
		m.ClearDateErased()
		return nil
	case FieldDateCreated:
		m.ClearDateCreated()
		return nil
	case FieldBillingAccountId:
		m.ClearBillingAccountId()
		return nil
	case FieldOfferId:
		m.ClearOfferId()
		return nil
	}
	return fmt.Errorf("unknown Link nullable field %s", name)
}

// ResetField resets all changes in the mutation for the field with the given name.
// It returns an error if the field is not defined in the schema.
func (m *Mutation) ResetField(name string) error {
	switch name {
	case FieldPayer:
		m.ResetPayer()
		return nil
	case FieldDateStart:
		m.ResetDateStart()
		return nil
	case FieldDateEnd:
		m.ResetDateEnd()
		return nil
	case FieldBegan:
		m.ResetBegan()
		return nil
	case FieldEnded:
		m.ResetEnded()
		return nil
	case FieldDateUpdated:
		m.ResetDateUpdated()
		return nil
	case FieldDateErased:
		m.ResetDateErased()
		return nil
	case FieldDateCreated:
		m.ResetDateCreated()
		return nil
	case FieldTenantId:
		m.ResetTenantId()
		return nil
	case FieldWorkspaceId:
		m.ResetWorkspaceId()
		return nil
	case FieldBillingAccountId:
		m.ResetBillingAccountId()
		return nil
	case FieldOfferId:
		m.ResetOfferId()
		return nil
	}
	return fmt.Errorf("unknown Link field %s", name)
}

// AddedEdges returns all edge names that were set/added in this mutation.
func (m *Mutation) AddedEdges() []string {
	edges := make([]string, 0, 4)
	if m.tenant != nil {
		edges = append(edges, EdgeTenant)
	}
	if m.workspace != nil {
		edges = append(edges, EdgeWorkspace)
	}
	if m.billing_account != nil {
		edges = append(edges, EdgeBillingAccount)
	}
	if m.offer != nil {
		edges = append(edges, EdgeOffer)
	}
	return edges
}

// AddedIds returns all Ids (to other nodes) that were added for the given edge
// name in this mutation.
func (m *Mutation) AddedIds(name string) []ent.Value {
	switch name {
	case EdgeTenant:
		if id := m.tenant; id != nil {
			return []ent.Value{*id}
		}
	case EdgeWorkspace:
		if id := m.workspace; id != nil {
			return []ent.Value{*id}
		}
	case EdgeBillingAccount:
		if id := m.billing_account; id != nil {
			return []ent.Value{*id}
		}
	case EdgeOffer:
		if id := m.offer; id != nil {
			return []ent.Value{*id}
		}
	}
	return nil
}

// RemovedEdges returns all edge names that were removed in this mutation.
func (m *Mutation) RemovedEdges() []string {
	edges := make([]string, 0, 4)
	return edges
}

// RemovedIds returns all Ids (to other nodes) that were removed for the edge with
// the given name in this mutation.
func (m *Mutation) RemovedIds(name string) []ent.Value {
	return nil
}

// ClearedEdges returns all edge names that were cleared in this mutation.
func (m *Mutation) ClearedEdges() []string {
	edges := make([]string, 0, 4)
	if m.clearedtenant {
		edges = append(edges, EdgeTenant)
	}
	if m.clearedworkspace {
		edges = append(edges, EdgeWorkspace)
	}
	if m.clearedbilling_account {
		edges = append(edges, EdgeBillingAccount)
	}
	if m.clearedoffer {
		edges = append(edges, EdgeOffer)
	}
	return edges
}

// EdgeCleared returns a boolean which indicates if the edge with the given name
// was cleared in this mutation.
func (m *Mutation) EdgeCleared(name string) bool {
	switch name {
	case EdgeTenant:
		return m.clearedtenant
	case EdgeWorkspace:
		return m.clearedworkspace
	case EdgeBillingAccount:
		return m.clearedbilling_account
	case EdgeOffer:
		return m.clearedoffer
	}
	return false
}

// ClearEdge clears the value of the edge with the given name. It returns an error
// if that edge is not defined in the schema.
func (m *Mutation) ClearEdge(name string) error {
	switch name {
	case EdgeTenant:
		m.ClearTenant()
		return nil
	case EdgeWorkspace:
		m.ClearWorkspace()
		return nil
	case EdgeBillingAccount:
		m.ClearBillingAccount()
		return nil
	case EdgeOffer:
		m.ClearOffer()
		return nil
	}
	return fmt.Errorf("unknown Link unique edge %s", name)
}

// ResetEdge resets all changes to the edge with the given name in this mutation.
// It returns an error if the edge is not defined in the schema.
func (m *Mutation) ResetEdge(name string) error {
	switch name {
	case EdgeTenant:
		m.ResetTenant()
		return nil
	case EdgeWorkspace:
		m.ResetWorkspace()
		return nil
	case EdgeBillingAccount:
		m.ResetBillingAccount()
		return nil
	case EdgeOffer:
		m.ResetOffer()
		return nil
	}
	return fmt.Errorf("unknown Link edge %s", name)
}
